param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-char-span-formatting-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DecimalThrowingProvider'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$builder=$assembly.DefineDynamicModule('Main').DefineType('ThrowingProvider',[Reflection.TypeAttributes]'Public,Sealed');$builder.AddInterfaceImplementation([IFormatProvider]);$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public)|Out-Null;$method=$builder.DefineMethod('GetFormat',[Reflection.MethodAttributes]'Public,Virtual,Final,HideBySig,NewSlot',[object],[type[]]@([type]));$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'provider failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,[IFormatProvider].GetMethod('GetFormat'));$throwing=[Activator]::CreateInstance($builder.CreateType())
$custom=[Globalization.NumberFormatInfo]::new();$custom.NegativeSign='~';$custom.PositiveSign='^';$custom.NumberDecimalSeparator='@';$custom.NumberGroupSeparator='_';$custom.NumberGroupSizes=[int[]]@(2,3);$custom.CurrencySymbol='USD';$custom.CurrencyDecimalSeparator=':';$custom.CurrencyGroupSeparator="'";$custom.CurrencyGroupSizes=[int[]]@(3,2);$custom.CurrencyPositivePattern=2;$custom.CurrencyNegativePattern=14;$custom.NumberNegativePattern=4;$custom.PercentSymbol='%!'
function New-DecimalFormatter(){
 $span=[type]'System.Span[char]';$bridge=[Reflection.Emit.DynamicMethod]::new('DecimalSliceTryFormat',[bool],[type[]]@([object],[char[]],[int],[int],[int[]],[string],[IFormatProvider]));$il=$bridge.GetILGenerator()
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Castclass,[ISpanFormattable]);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@([char[]],[int],[int])))
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int]);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Call,[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[ISpanFormattable].GetMethod('TryFormat'));$il.Emit([Reflection.Emit.OpCodes]::Ret)
 return $bridge.CreateDelegate([Func[object,char[],int,int,int[],string,IFormatProvider,bool]])
}
$formatter=New-DecimalFormatter;$formattable=[IFormattable].GetMethod('ToString',[type[]]@([string],[IFormatProvider]));$buffers=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);foreach($format in $plan.formats){foreach($profile in $plan.providers){$provider=$null;switch($profile){'invariant'{$provider=[Globalization.NumberFormatInfo]::InvariantInfo};'custom'{$provider=$custom};'throwing'{$provider=$throwing}};$arguments=[object[]]::new(2);$arguments[0]=$format;$arguments[1]=$provider
 try{$text=[string]$formattable.Invoke($value,$arguments);$length=$text.Length;$capacities=@(0,1,[Math]::Max(0,$length-1),$length,($length+1))|Sort-Object -Unique}catch{$capacities=@(0,1,3,7,32)}
 foreach($capacity in $capacities){foreach($route in $plan.routes){$offset=if($route -eq 'array'){0}else{2};$suffix=if($route -eq 'array'){0}else{3};$buffer=[char[]]('#'*($capacity+$offset+$suffix));$written=[int[]]@(99)
  try{$actual=$formatter.Invoke($value,$buffer,$offset,$capacity,$written,$format,$provider);$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_}
  $buffers.Add([ordered]@{index=$index;format=$format;provider=$profile;route=$route;capacity=$capacity;offset=$offset;suffix=$suffix;result=$result;written=$written[0];bufferUnits=[int[]][char[]]$buffer;afterBits=[decimal]::GetBits($value)})
 }}
}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';spanAssignable=[ISpanFormattable].IsAssignableFrom([decimal]);utf8Assignable=[IUtf8SpanFormattable].IsAssignableFrom([decimal]);buffers=$buffers.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 22 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal Char span capture: $($buffers.Count) buffers"
